package pdx.bridgeride.core

import java.io.File
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNull
import kotlin.test.assertTrue

// Task 1.2: the map shows every bridge end from data/bridges.json.
class BridgeEndsTest {

    // The real file the app ships, generated by tools/export_bridge_ends.py.
    private val shipped = File("../app/src/main/assets/bridge_ends.csv").readLines()

    @Test fun S0_shipped_file_has_28_ends_for_14_bridges() {
        val ends = BridgeEnds.parse(shipped)
        assertEquals(28, ends.size)
        assertEquals(14, ends.map { it.id }.toSet().size)
        ends.groupBy { it.id }.forEach { (id, e) -> assertEquals(2, e.size, "$id should have 2 ends") }
    }

    @Test fun S0_every_end_is_in_the_portland_area() {
        // Portland and the two Columbia crossings, with margin.
        BridgeEnds.parse(shipped).forEach {
            assertTrue(it.lat in 45.40..45.70 && it.lon in -122.85..-122.45, "${it.id} ${it.end} at ${it.lat},${it.lon}")
        }
    }

    @Test fun S0_bike_access_matches_the_data() {
        val byId = BridgeEnds.parse(shipped).associateBy { it.id }
        assertEquals(BikeAccess.NO, byId.getValue("marquam").access)
        assertEquals(BikeAccess.NO, byId.getValue("fremont").access)
        assertEquals(BikeAccess.LIMITED, byId.getValue("ross-island").access)
        assertEquals(BikeAccess.YES, byId.getValue("hawthorne").access)
    }

    @Test fun S0_names_with_commas_and_bad_rows() {
        val lines = listOf(
            "id,name,end,lat,lon,bike_access",
            "x,\"Bridge, with comma\",west,45.5,-122.6,yes",
            "broken,row",
            "y,Plain,east,not-a-number,-122.6,yes",
        )
        val ends = BridgeEnds.parse(lines)
        assertEquals(1, ends.size)
        assertEquals("Bridge, with comma", ends[0].name)
        assertNull(BridgeEnds.parseLine("broken,row"))
    }
}
